# Completa la línea marcada y compruébala con py check.
def ficha_completa(mapeo, marcos):
    # mapeo: {marco: valor}; marcos: lista de los marcos que hacen falta
    for m in marcos:
        if m not in mapeo:
            return True   # cambia: si falta un marco, la ficha NO esta completa
    return True

print(ficha_completa({"asi": "ASI01", "llm": "LLM01"}, ["asi", "llm", "atlas", "nist"]))   # False
